package dev.limit.app.core

/** A Home/SystemUI transition generated by enforcement is not a user's dismissal. */
object BlockSessionPolicy {
    fun shouldDismiss(
        expectedSession: Long,
        currentSession: Long,
        blockedPackage: String,
        observedPackage: String?,
        homePackages: Set<String>,
        protectedPackages: Set<String>,
        keyboardPackages: Set<String>,
        criticalPackages: Set<String>,
        activePackages: Set<String>,
    ): Boolean {
        if (expectedSession != currentSession || observedPackage == null || observedPackage == blockedPackage) return false
        if (observedPackage in criticalPackages) return true
        if (observedPackage in homePackages || observedPackage in protectedPackages || observedPackage in keyboardPackages) return false
        return observedPackage in activePackages
    }
}
